            document.getElementById('expression-value').innerText = SafeGetValue(stat_data, '角色状态.面部表情.0');
            document.getElementById('mouth-value').innerText = SafeGetValue(stat_data, '角色状态.口.0');
            document.getElementById('tongue-value').innerText = SafeGetValue(stat_data, '角色状态.舌头.0');
