            document.getElementById('breasts-value').innerText = SafeGetValue(stat_data, '角色状态.乳房.0');
            document.getElementById('abdomen-value').innerText = SafeGetValue(stat_data, '角色状态.腹部.0');
            document.getElementById('vagina-value').innerText = SafeGetValue(stat_data, '角色状态.小穴.0');
            document.getElementById('anus-value').innerText = SafeGetValue(stat_data, '角色状态.菊穴.0');
            document.getElementById('legs-value').innerText = SafeGetValue(stat_data, '角色状态.双腿.0');
            document.getElementById('feet-value').innerText = SafeGetValue(stat_data, '角色状态.足.0');

            const affection = SafeGetValue(stat_data, '吸血鬼攻略.对 {{user}}的好感度.0', 0);
